(function (all) { var mine = all["ar"] = all["ar"] || {}; var add = {"nav.skip":"الانتقال إلى المحتوى","nav.site":"الموقع","nav.home":"الرئيسية","nav.features":"الميزات","nav.documentation":"التوثيق","nav.changelog":"سجل التغييرات","nav.language":"اللغة","hero.tagline":"سجِّل وبُثَّ كما في الاستوديو — مشاهد ومصادر وبث متعدد، في تطبيق واحد أنيق.","hero.sub":"استوديو للبث المباشر والتسجيل على Windows وmacOS وLinux. بلا حسابات ولا قياس عن بُعد ولا خدمة سحابية تابعة لنا: يذهب بثّك مباشرة إلى المنصات التي تختارها.","notice.price":"Freally Capture مجاني اليوم، لكنه قد لا يبقى مجانيًا إلى الأبد: قد تُباع الإصدارات المستقبلية.","hero.chipDesktop":"تطبيق لسطح المكتب","hero.noDownloads":"الإصدار الحالي هو 1.2.1. لا توجد أي تنزيلات على هذا الموقع، والشيفرة المصدرية خاصة.","what.title":"ما هو","what.p1":"يتطلب البث المباشر عادةً تطبيقًا للالتقاط، وآخر لمزج الصوت، وخدمة ترسل البث إلى عدة منصات، وحسابًا لدى كل منها.","what.p2":"Freally Capture استوديو واحد على حاسوبك أنت. ابنِ مشهدًا من شاشتك ونوافذك وكاميراتك ووسائطك وطبقاتك؛ ركّبه على بطاقة الرسوميات؛ سجّله على ما يصل إلى ست مسارات صوتية؛ وبُثّه إلى عدة منصات في آنٍ واحد، مباشرة من جهازك دون أي وسيط.","what.p3":"لا يحتاج إلى حساب ولا يرسل أي بيانات قياس عن بُعد. ما يغادر حاسوبك هو البث الذي اخترت إرساله، إضافة إلى اتصالات قليلة تشغّلها بنفسك — وكلٌّ منها موضّح بجلاء في التوثيق.","features.title":"ما الذي يحتويه","features.scenes.title":"مشاهد على وحدة الرسوميات","features.scenes.body":"ابنِ مشاهد من الشاشات والنوافذ والألعاب والكاميرات وصفحات الويب والوسائط والصور والنصوص، وركّبها مباشرة على بطاقة الرسوميات مع المرشّحات والانتقالات.","features.multistream.title":"بث متعدد ومباشر","features.multistream.body":"ابدأ البث على Twitch أو YouTube أو Kick أو Facebook أو Trovo أو على خادمك الخاص — على عدة منصات معًا — عبر RTMP أو RTMPS أو SRT أو WHIP، مباشرة من جهازك.","features.record.title":"تسجيل متعدد المسارات","features.record.body":"سجّل بمرمّز العتاد في بطاقة الرسوميات أو دون فقد بتنسيق Capture الخاص، على ما يصل إلى ست مسارات صوتية، مع تقسيم الملفات وعلامات الفصول وملفات تصمد أمام الأعطال.","features.audio.title":"مازج للبث","features.audio.body":"لكل مصدر شريطه الخاص، مع كبت الضوضاء والبوابة والضاغط والمعادل وقياس الجهارة — كلها معالجة إشارة كلاسيكية، ولا ذكاء اصطناعي في أي مكان.","features.safety.title":"وضع الاستوديو والأمان","features.safety.body":"حضّر التغييرات في المعاينة قبل أن تُبث، وافحص كل شيء بفحص ما قبل البث، وأبقِ الإنذارات والتحويل الاحتياطي للمرمّز وزر الطوارئ جاهزة.","features.guests.title":"ضيوف عن بُعد","features.guests.body":"ادعُ حتى ثمانية ضيوف برابط واحد. ينضمون من متصفح الويب، وتصلك كاميراتهم وميكروفوناتهم مباشرة، من نظير إلى نظير.","features.deep.title":"كاميرا افتراضية، ومصدر متصفح، والتقاط الألعاب","features.deep.body":"برنامجك ككاميرا ويب لمكالمات الفيديو، وأي صفحة ويب كمصدر، والألعاب في وضع ملء الشاشة الحصري — على Windows أولًا، مع ذكر كل نقص بصراحة.","features.free.title":"مجاني اليوم، محلي، بلا ذكاء اصطناعي","features.free.body":"لا خطة مدفوعة ولا حساب ولا قياس عن بُعد ولا نموذج. تبقى مشاهدك وتسجيلاتك ومفاتيح البث على حاسوبك.","ladder.title":"إصدارًا بعد إصدار","ladder.intro":"كل إصدارات Freally Capture حتى الآن، من الأساس إلى الإصدار الحالي. تفاصيل كل إصدار في سجل التغييرات.","ladder.version":"الإصدار","ladder.state":"الحالة","ladder.lands":"ما الذي جاء به","ladder.state.done":"منجز","ladder.rung.v0.10.0":"الأساس: واجهة تطبيق سطح المكتب فوق محرّكه الخاص، وفحوص البناء على Windows وmacOS وLinux، وهذا الموقع.","ladder.rung.v0.25.0":"الالتقاط: الشاشات والنوافذ وكاميرات الويب على Windows وmacOS وLinux، مباشرة في المعاينة.","ladder.rung.v0.40.0":"مُركِّب وحدة الرسوميات: مشاهد تُبنى من المصادر وتُركَّب على بطاقة الرسوميات، مع مرشّحات مثل مفتاح الكروما وتصحيح الألوان وجداول LUT والتمويه.","ladder.rung.v0.55.0":"الصوت والتسجيل: مازج حتى ست مسارات بمرشّحات DSP كلاسيكية، وتسجيل متعدد المسارات بمرمّزات العتاد وتنسيق Capture الخاص بلا فقد.","ladder.rung.v0.56.0":"معاينة أصلية على وحدة الرسوميات: يُرسم البرنامج مباشرة من المُركِّب، دون أي تأخير.","ladder.rung.v0.70.0":"الاستوديو: البث إلى Twitch وYouTube وKick وFacebook وTrovo مع إعادة الاتصال التلقائية، ووضع الاستوديو مع الانتقالات، واختصارات المفاتيح، والملفات الشخصية، ولوحة الإحصاءات.","ladder.rung.v0.85.0":"تعمّق في البث: بث متعدد إلى عدة منصات معًا، وSRT وWHIP، ولوحة عمودية، ومشاهد متداخلة، ومخزن إعادة، وطبقة دردشة لا تتطلب تسجيل الدخول.","ladder.rung.v0.90.0":"التحكم عن بُعد والإضافات: واجهة WebSocket API محمية بكلمة مرور، ولوحات متصفح، ونصوص Lua برمجية في بيئة معزولة، وحزمة SDK للإضافات، وكلها محلية ومعطّلة افتراضيًا.","ladder.rung.v0.95.0":"التوزيع: محدِّث تلقائي موقَّع، والتقاط الصوت لكل تطبيق على حدة، واتفاقية الترخيص عند أول تشغيل.","ladder.rung.v0.96.0":"استوديو للجميع: 18 لغة، ودعم كامل للوحة المفاتيح وقارئات الشاشة، ومعالج إعداد عند أول تشغيل، ولوحة أوامر، وسمات.","ladder.rung.v0.97.0":"تأليف المشاهد ومراقبتها: التراجع والإعادة، ومستورِد لمجموعات مشاهد OBS، وأدلة محاذاة، ومنضدة للعزل اللوني، وعرض متعدد، وأجهزة عرض.","ladder.rung.v0.98.0":"أمان البث: فحص ما قبل البث، وإنذارات، ولوحة لصحة المصادر، وتحويل احتياطي للمرمّز، وتسجيل يصمد أمام الأعطال، وزر طوارئ، وحماية عند الإغلاق.","ladder.rung.v0.99.0":"المصادر والأجهزة والمعايرة: إشارات اختبار، ومعايرة تزامن الصوت والصورة، ومؤقّتات وساعات، ونص من ملف، وخريطة للاختصارات، وإزالة التشابك، والتحكم في الكاميرا.","ladder.rung.v0.200.0":"تعمّق في الأتمتة والالتقاط: قواعد، ووحدات ماكرو، وتحكم عبر MIDI وOSC، ولوحة لمس على الشبكة المحلية، وأضواء Tally، وكاميرات PTZ، وجدول سير للبرنامج، إضافة إلى التقريب الاقتطاعي وتعيين النغمات من HDR إلى SDR.","ladder.rung.v0.300.0":"مصادر وطبقات جديدة: إعادة فورية، وقائمة تشغيل بلا فواصل، ومصمّم للعناوين ولوحات النتائج، ومُصوِّر للصوت، وطبقة إحصاءات، ومؤقّت للمراحل، وطبقة لعرض المدخلات، واستقبال عبر الشبكة المحلية، وFreally Link.","ladder.rung.v0.400.0":"تعمّق في المُركِّب: تثبيت الزوايا ثلاثي الأبعاد، ومفاتيح المخرج النهائي، وتجميد الإطار، ومزيد من أنواع التمويه، وانتقال الحركة، واستوديو لمظلّلات WGSL، وأقنعة بيزييه، وفواصل انتقالية بقناع مسار.","ladder.rung.v0.500.0":"إنتاج الصوت: توجيه المخارج، ومصفوفة خفض الصوت، ومازج تلقائي، وتطبيع الجهارة، ومعادل بارامتري، ولوحة أصوات، وتسجيل البودكاست، واكتشاف إضافات CLAP وVST3.","ladder.rung.v0.600.0":"تعمّق في التسجيل والإعادة: تسجيل ISO لكل مصدر، وأداة لقصّ المقاطع، وتسجيل مع الشفافية، وعلامات تلقائية، وسلسلة معالجة بعد التسجيل، وفحص للسلامة، ورمز زمني SMPTE.","ladder.rung.v0.700.0":"فهم البث: محاكٍ للشبكة، ووضع للتمرين، وخط زمني للإطارات المفقودة، وتقرير للجلسة، واختبار أداء للمرمّزات، ومصادر لا تظهر إلا في البث أو إلا في التسجيل.","ladder.rung.v0.800.0":"الضيوف عن بُعد وإنتاج البرامج: حتى ثمانية ضيوف، وغرفة انتظار، وإشارات، ولوحة لجودة الاتصال، وأداة للرسم على الشاشة، وملقّن، وشبكات تلقائية للضيوف.","ladder.rung.v0.900.0":"إدارة الاستوديو: حزم المشاهد، والمقارنة والدمج، ولقطات محفوظة بأسماء، ووضع محمول، ونسخ احتياطي في ملف واحد، ومحرّر للسمات، وتخطيطات للوحات.","ladder.rung.v0.910.0":"الملقّن بحلّة جديدة: شارات التوقف، وعدّ تنازلي للبدء، وإيقاع بوحدة BPM، والقراءة بصوت عالٍ، والإكمال التلقائي في اللغات الثماني عشرة كلها.","ladder.rung.v1.0.0":"أول إصدار مستقر: كل الميزات المخطط لها، إضافة إلى عدّ تنازلي «سنبدأ قريبًا»، وموسيقى خلفية، وشريط للتواصل الاجتماعي، ولافتة لرسالة دردشة مميّزة.","ladder.rung.v1.1.0":"ملف MP4 سهل المشاركة، يُكتب بجوار كل تسجيل بلا فقد عند إيقافه.","ladder.rung.v1.2.0":"التقاط متعمّق والويب: كاميرا افتراضية، ومصدر متصفح حقيقي، والتقاط الألعاب، على Windows أولًا.","ladder.rung.v1.2.1":"التدقيق: لا ميزات جديدة، بل مراجعة شاملة للأمان والصحة، وأصبحت الإضافات الثلاث في 1.2.0 تعمل فعلًا.","ladder.note":"كل إصدار مُدرج منجز. ما سيأتي بعد 1.2.1 يُخطَّط له بشكل خاص، وسيظهر هنا عند إصداره. لا يمكن تنزيل أي منها من هذا الموقع.","honest.title":"الأشياء التي تضعها معظم المواقع في الأسفل","honest.windows.title":"بعض أحدث الميزات تعمل على Windows فقط","honest.windows.body":"في 1.2.1 تعمل الكاميرا الافتراضية والتقاط الألعاب وتأثيرات المؤشر على Windows فقط، وقد جرى التحقق من مصدر المتصفح على Windows أولًا. أما بقية الاستوديو فيعمل على Windows وmacOS وLinux.","honest.signed.title":"مكوّنان لم يُوقَّعا رقميًا بعد","honest.signed.body":"لم يُوقَّع بعدُ المكوّن النظامي للكاميرا الافتراضية ولا بيئة تشغيل مصدر المتصفح، ولا يزال اختباران حيّان معلّقين: الكاميرا داخل مكالمة فيديو حقيقية، والتقاط الألعاب في لعبة محمية. يذكر سجل التغييرات ذلك في الإصدار الذي أضافهما.","honest.network.title":"ما الذي يتصل بالإنترنت فعلًا","honest.network.body":"تذهب بثوثك إلى المنصات التي تعدّها. يمرّ إنشاء الاتصال في جلسة الضيوف عبر خدمة إشارات عامة؛ وتقرأ طبقة الدردشة الدردشة العامة لقناة ما؛ ويُنزَّل ffmpeg وبيئة تشغيل المتصفح أول مرة تحتاج إليهما؛ ويتحقق التطبيق من التحديثات؛ ولا يُرسَل بلاغ المشكلة إلا عندما تضغط «إرسال» في صفحته. وباستثناء التحقق من التحديثات، لا يحدث أي من ذلك إلا لأنك أعددته بنفسك.","honest.downloads.title":"لا توجد تنزيلات هنا","honest.downloads.body":"يصف هذا الموقع Freally Capture ولا يوزّعه. لا توجد صفحة تنزيل ولا رابط ولا زر، والشيفرة المصدرية خاصة.","footer.licence":"ملكية خاصة — جميع الحقوق محفوظة. © Mike Weaver. الاستخدام مجاني اليوم؛ وقد تُباع الإصدارات المستقبلية. ليس مفتوح المصدر.","footer.yours":"ما تسجّله وتبثّه ملكٌ لك، وكذلك المسؤولية عنه. لا يتلقى مؤلف Freally Capture أي شيء منه ولا يخزّنه ولا يمرّره.","featuresPage.title":"كل ما يفعله","featuresPage.lead":"استوديو للبث المباشر والتسجيل على حاسوبك أنت: مشاهد تُركَّب على بطاقة الرسوميات، وتسجيل متعدد المسارات، وبث متعدد إلى كل المنصات معًا، مباشرة من جهازك.","featuresPage.version":"تصف هذه الصفحة Freally Capture 1.2.1، الإصدار المنشور: كل ما فيها موجود في 1.2.1، ولا يرد فيها شيء مما خُطِّط له لاحقًا.","featuresPage.numbers.title":"بالأرقام","featuresPage.numbers.intro":"كل رقم هو ما يفعله الإصدار 1.2.1، محسوبًا من شيفرته وسجل تغييراته. لا شيء مقرّب إلى الأعلى.","featuresPage.numbers.systems":"أنظمة تشغيل: Windows وmacOS وLinux","featuresPage.numbers.protocols":"بروتوكولات بث: RTMP وRTMPS وSRT وWHIP","featuresPage.numbers.platforms":"منصات مدمجة — Twitch وYouTube وKick وFacebook وTrovo — إضافة إلى أي خادم خاص بك","featuresPage.numbers.tracks":"مسارات صوتية في تسجيل واحد","featuresPage.numbers.encoders":"عائلات من مرمّزات العتاد: NVENC وQuick Sync وAMF وVAAPI وVideoToolbox","featuresPage.numbers.guests":"ضيوف عن بُعد في جلسة واحدة","featuresPage.numbers.languages":"لغة","featuresPage.numbers.accounts":"حسابات عليك إنشاؤها","featuresPage.numbers.ai":"نماذج ذكاء اصطناعي","featuresPage.numbers.price":"السعر اليوم","featuresPage.free.title":"مجاني اليوم","featuresPage.free.body":"كل ما يفعله Freally Capture اليوم مجاني للجميع: لا خطة مدفوعة، ولا اشتراك، ولا حساب، ولا علامة مائية، ولا فترة تجربة تنتهي. ما تسجّله وتبثّه ملكٌ لك.","featuresPage.cards.title":"ما يفعله الإصدار 1.2.1","featuresPage.cards.scenes.title":"مشاهد ومصادر على وحدة الرسوميات","featuresPage.cards.scenes.body":"الشاشات والنوافذ والألعاب وكاميرات الويب وبطاقات الالتقاط وصفحات الويب والوسائط وقوائم التشغيل والصور والنصوص والمؤقّتات وإشارات الاختبار، مركّبة مباشرة على بطاقة الرسوميات. مشاهد متداخلة، ومجموعات، ومصادر مشتركة، ولوحة عمودية 9:16، والتراجع عن كل تعديل.","featuresPage.cards.effects.title":"المرشّحات والانتقالات","featuresPage.cards.effects.body":"مفتاح الكروما، وتصحيح الألوان، وجداول LUT، والأقنعة، وعائلة من أنواع التمويه، والإمالة ثلاثية الأبعاد، ومظلّلات WGSL الخاصة بك، على كل مصدر. القطع، والتلاشي، والانزلاق، والفاصل الانتقالي، والمسح بالسطوع، وانتقال الحركة الذي ينقل العناصر بسلاسة من مشهد إلى آخر.","featuresPage.cards.studio.title":"وضع الاستوديو والمراقبة","featuresPage.cards.studio.body":"حضّر اللقطة التالية في المعاينة وأرسلها إلى البرنامج حين تجهز. عرض متعدد، وأجهزة عرض بملء الشاشة على أي شاشة، ومفاتيح المخرج النهائي فوق كل مشهد، ولوحة إحصاءات بأرقام حقيقية.","featuresPage.cards.multistream.title":"بث متعدد، مباشرة من جهازك","featuresPage.cards.multistream.body":"ابدأ البث على عدة منصات معًا عبر RTMP أو RTMPS أو SRT أو WHIP، دون أي خدمة وسيطة. كل وجهة تعيد الاتصال وحدها، فلا تُسقط وجهةٌ متعطلة بقيةَ الوجهات أبدًا.","featuresPage.cards.recording.title":"تسجيلات تصمد","featuresPage.cards.recording.body":"مرمّزات العتاد، مع x264 احتياطيًا، إلى MP4 أو MKV أو MOV أو WebM، أو بتنسيق Capture الخاص بلا فقد؛ حتى ست مسارات صوتية؛ ملف نظيف لكل مصدر؛ تسجيلات تنجو من الأعطال، وإصلاح عند التشغيل التالي.","featuresPage.cards.audio.title":"وحدة تحكم صوتية للبث","featuresPage.cards.audio.body":"كبت الضوضاء والبوابة والضاغط والمحدِّد والمعادل البارامتري ومزيل الصفير على كل شريط، إلى جانب خفض الصوت والمازج التلقائي وتطبيع الجهارة ولوحة الأصوات وتسجيل البودكاست. معالجة إشارة كلاسيكية، بلا ذكاء اصطناعي.","featuresPage.cards.replay.title":"الإعادة الفورية","featuresPage.cards.replay.body":"مخزن إعادة يعمل باستمرار ويحفظ اللحظات الأخيرة بضغطة مفتاح، ومصدر إعادة يعيدها إلى البث بالسرعة الكاملة أو بنصفها أو بربعها. وتُصدِّر أداة قصّ المقاطع دون إعادة ترميز متى أمكن.","featuresPage.cards.guests.title":"ضيوف من المتصفح","featuresPage.cards.guests.body":"ينضم حتى ثمانية ضيوف عبر رابط، في متصفح الويب، دون تثبيت أي شيء. غرفة انتظار، وإشارات خاصة، واتصال كل ضيف في لمحة، وشبكة تلقائية بلافتات الأسماء.","featuresPage.cards.safety.title":"أمان البث","featuresPage.cards.safety.body":"فحص قبل البث، وإنذارات للصمت والتشبّع وتجمّد الصورة وامتلاء القرص، وتحويل احتياطي للمرمّز وسط البرنامج، وزر طوارئ، ووضع تمرين لا يرسل شيئًا، وإغلاق ينهي كل شيء بالترتيب.","featuresPage.cards.automation.title":"الأتمتة والتحكم","featuresPage.cards.automation.body":"قواعد ووحدات ماكرو ومتغيّرات؛ وأجهزة تحكم MIDI وOSC؛ ولوحة لمس وأضواء Tally على هاتفك؛ وكاميرات PTZ؛ وجدول سير للبرنامج؛ وواجهة WebSocket API لجهاز Stream Deck؛ ونصوص Lua وإضافات. كلها معطّلة افتراضيًا.","featuresPage.cards.deep.title":"كاميرا افتراضية، ومصدر متصفح، والتقاط الألعاب","featuresPage.cards.deep.body":"برنامجك ككاميرا ويب لتطبيقات مكالمات الفيديو؛ وأي صفحة ويب تُعرض كمصدر؛ والألعاب في وضع ملء الشاشة الحصري عبر خطّاف توافق عليه لعبةً لعبة. على Windows أولًا، والنواقص مذكورة أدناه.","featuresPage.cards.private.title":"محلي، خاص، بلا ذكاء اصطناعي","featuresPage.cards.private.body":"لا حساب ولا قياس عن بُعد ولا خدمة سحابية تابعة لنا. تبقى تسجيلاتك ومفاتيح البث على حاسوبك، ولا يستخدم أي مرشّح نموذجًا: كلها معالجة إشارة كلاسيكية.","featuresPage.compare.title":"جنبًا إلى جنب مع الاستوديوهات التجارية","featuresPage.compare.intro":"Freally Capture إلى جانب الاستوديوهات التجارية التي يستخدمها الناس للبث والتسجيل. عمود Capture هو الإصدار المنشور 1.2.1. كل خانة لمنتج آخر مأخوذة من صفحات الشركة المصنّعة نفسها، وقد جرى التحقق منها في 2 أكتوبر 2026، والأسعار هي أسعار القائمة الأمريكية في أكتوبر 2026.","featuresPage.compare.legend.yes":"متوفر","featuresPage.compare.legend.partly":"جزئيًا","featuresPage.compare.legend.no":"غير متوفر","featuresPage.compare.legend.unknown":"لم يُتحقَّق منه","featuresPage.compare.feature":"الميزة","featuresPage.compare.row.price":"السعر (USD، أكتوبر 2026)","featuresPage.compare.freeToday":"مجاني اليوم","featuresPage.compare.price.streamlabs":"27 دولارًا شهريًا أو 189 دولارًا سنويًا","featuresPage.compare.price.xsplit":"14.99 دولارًا شهريًا، أو 59.99 دولارًا سنويًا، أو 119.99 دولارًا مرة واحدة","featuresPage.compare.price.vmix":"1,200 دولار مرة واحدة","featuresPage.compare.price.wirecast":"79 دولارًا شهريًا، أو 504 دولارات سنويًا","featuresPage.compare.price.ecamm":"40 دولارًا شهريًا أو 384 دولارًا سنويًا","featuresPage.compare.price.restream":"19 دولارًا شهريًا أو 190 دولارًا سنويًا","featuresPage.compare.row.systems":"يعمل على Windows وmacOS وLinux","featuresPage.compare.note.browser":"في متصفح ويب","featuresPage.compare.row.multistream":"يبث إلى عدة منصات في آنٍ واحد","featuresPage.compare.note.channels3":"3 قنوات في هذه الخطة","featuresPage.compare.row.direct":"…مباشرة من حاسوبك، دون خدمة وسيطة","featuresPage.compare.note.servers":"عبر خوادم الشركة المصنّعة","featuresPage.compare.row.srt":"إخراج SRT","featuresPage.compare.note.business":"من خطة Business فما فوق","featuresPage.compare.row.whip":"إخراج WHIP (WebRTC)","featuresPage.compare.note.customStream":"إخراج «Custom Stream»","featuresPage.compare.note.beta":"إصدار تجريبي","featuresPage.compare.row.vcam":"كاميرا افتراضية لمكالمات الفيديو","featuresPage.compare.note.windowsOnly":"Windows فقط حاليًا","featuresPage.compare.row.guests":"ينضم الضيوف من متصفح الويب","featuresPage.compare.note.p2p":"حتى 8، من نظير إلى نظير","featuresPage.compare.note.collab":"حتى 11 ضيفًا أو كاميرا","featuresPage.compare.note.vmixCall":"حتى 8، عبر vMix Call","featuresPage.compare.note.rendezvous":"حتى 7، عبر Rendezvous","featuresPage.compare.note.ecammGuests":"حتى 10 على Apple Silicon","featuresPage.compare.note.restreamGuests":"10 على الشاشة، مع المضيف","featuresPage.compare.row.replay":"الإعادة الفورية","featuresPage.compare.row.tracks":"عدة مسارات صوتية في تسجيل واحد","featuresPage.compare.note.tracks6":"حتى 6 مسارات","featuresPage.compare.note.tracks5":"5 مسارات","featuresPage.compare.note.channels":"كقنوات، بتنسيق AVI أو WAV فقط","featuresPage.compare.note.tracks8":"حتى 8 مسارات","featuresPage.compare.note.separateFiles":"كملفات منفصلة","featuresPage.compare.note.professional":"من خطة Professional فما فوق","featuresPage.compare.row.account":"يعمل دون حساب","featuresPage.compare.note.recordingOnly":"للتسجيل فقط","featuresPage.compare.note.licenceAccount":"ترخيص مرتبط بحساب","featuresPage.compare.note.key":"مفتاح ترخيص","featuresPage.compare.note.signIn":"يتطلب تسجيل الدخول","featuresPage.compare.row.noAi":"بلا ميزات ذكاء اصطناعي","featuresPage.compare.note.aiHighlights":"أبرز لقطات الألعاب بالذكاء الاصطناعي","featuresPage.compare.note.aiBackground":"إزالة الخلفية بالذكاء الاصطناعي","featuresPage.compare.note.aiClips":"مقاطع وموسيقى بالذكاء الاصطناعي","featuresPage.compare.summary":"ما يملكه Freally Capture ولا يملكه غيره: هو تطبيق سطح المكتب الوحيد هنا الذي يعمل على Linux إلى جانب Windows وmacOS، والوحيد المجاني. أربعة من الستة يتطلبون حسابًا وأربعة فيها ميزات ذكاء اصطناعي؛ أما Capture فلا هذا ولا ذاك، ويبث إلى عدة منصات مباشرة من حاسوبك، بينما يمرّر Streamlabs وRestream بثّك عبر خوادمهما.","featuresPage.compare.theyWin":"حيث يتفوّقون: يسجّل Wirecast Pro حتى 8 مسارات صوتية مقابل 6 في Capture، ويستقبل Streamlabs Ultra حتى 11 ضيفًا أو كاميرا وEcamm حتى 10، مقابل 8 في Capture. ولدى Streamlabs وXSplit وvMix وWirecast وEcamm جميعها كاميرا افتراضية؛ أما كاميرا Capture فتعمل على Windows فقط في 1.2.1 ولم تُوقَّع رقميًا بعد.","featuresPage.compare.obs":"OBS Studio مجاني ومفتوح المصدر أيضًا، ويعمل على الأنظمة الثلاثة، وفيه SRT وWHIP وكاميرا افتراضية ومخزن إعادة وست مسارات صوتية. لكنه يحتاج إلى إضافة من طرف ثالث للبث إلى عدة منصات معًا؛ أما في Capture فهذه الميزة مدمجة، وكذلك الضيوف الذين ينضمون من المتصفح.","featuresPage.compare.asOf":"سعر Capture هو سعر اليوم: إنه مجاني اليوم، وقد تُباع الإصدارات المستقبلية. والمنتجات الأخرى تتغير أيضًا؛ هذا الجدول بحسب حالتها في 2 أكتوبر 2026.","featuresPage.why.title":"لماذا بُني بهذه الطريقة","featuresPage.why.local.title":"يبقى على جهازك","featuresPage.why.local.body":"لا ينبغي لأداة بث أن تتحوّل إلى «اربط قناتك». لا حساب تنشئه ولا وسيط تابعًا لنا في المنتصف: يذهب بثّك من حاسوبك إلى المنصات التي اخترتها.","featuresPage.why.owned.title":"محرّكه الخاص","featuresPage.why.owned.body":"المُركِّب ومحرّك الصوت وتنسيق التسجيل بلا فقد كلها ملك Capture. أما الترميزات التي تتطلبها المنصات فتأتي من ffmpeg، الذي يُنزَّل أول مرة تحتاج إليه بدلًا من أن يُضمَّن مع التطبيق.","featuresPage.why.dsp.title":"معالجة إشارة كلاسيكية","featuresPage.why.dsp.body":"كبت الضوضاء والعزل اللوني وتعيين النغمات معادلات لا نماذج. المدخل نفسه بالإعدادات نفسها يعطي النتيجة نفسها، ولا حاجة إلى تنزيل أي شيء لتعمل.","featuresPage.why.safe.title":"معطّل حتى تشغّله","featuresPage.why.safe.body":"كل مستمِع للشبكة، وكل أتمتة، وكل التقاط محفوف بالمخاطر معطّل افتراضيًا. يستأذنك التقاط الألعاب لكل لعبة، ولا يمكن لمجموعة مشاهد مُشارَكة أن تحمل هذا الإذن أبدًا.","featuresPage.why.honest.title":"صريح بشأن نواقصه","featuresPage.why.honest.body":"حين تعمل ميزة على نظام واحد فقط، أو لم تُوقَّع رقميًا بعد، أو لا تزال تنتظر اختبارًا حيًّا، يقول ذلك التطبيق وسجل التغييرات وهذه الصفحة.","featuresPage.limits.title":"ما لا يفعله 1.2.1","featuresPage.limits.vcam":"تعمل الكاميرا الافتراضية على Windows فقط؛ وكاميرات macOS وLinux ليست في هذا الإصدار.","featuresPage.limits.game":"يعمل التقاط الألعاب على Windows فقط وينسخ ألعاب Direct3D 11؛ أما ألعاب HDR وDirect3D 12 فتنتقل إلى التقاط النافذة.","featuresPage.limits.browser":"يعرض مصدر المتصفح صورة الصفحة، لكن ليس صوتها بعد.","featuresPage.limits.signed":"لم يُوقَّع بعدُ المكوّن النظامي للكاميرا الافتراضية ولا بيئة تشغيل المتصفح، ولا يزال اختباران حيّان معلّقين: الكاميرا داخل مكالمة فيديو حقيقية، والتقاط الألعاب في لعبة محمية.","featuresPage.limits.cursor":"تعمل تأثيرات المؤشر وطبقة عرض لوحة المفاتيح والفأرة على Windows فقط.","featuresPage.limits.ai":"لا يتضمن أي ميزات ذكاء اصطناعي — لا إزالة خلفية ولا ترجمة نصية ولا مقاطع أبرز اللقطات بالذكاء الاصطناعي — وذلك عن قصد.","featuresPage.limits.downloads":"لا توجد تنزيلات على هذا الموقع، ولا على هذه الصفحة.","docs.title":"التوثيق","docs.intro":"كيف تستخدم Freally Capture، الإصدار 1.2.1: تبني مشهدًا، وتسجّله، وتبدأ البث، وكل ما يحيط بذلك. ويذكر كل قسم الأنظمة التي تعمل عليها الميزة حين لا تعمل على الثلاثة جميعًا.","search.placeholder":"ابحث في التوثيق","docs.contents":"المحتويات","join.title":"انضم كضيف عن بُعد","join.button.join":"انضم بالكاميرا والميكروفون","join.button.leave":"مغادرة","join.greenRoom":"أنت في غرفة الانتظار — يفحص المضيف كاميرتك وميكروفونك. ستظهر على الهواء قريبًا.","join.cue":"إشارة","join.selfLabel":"أنت — هذا ما يتلقاه المضيف.","join.hostSharing":"يشارك المضيف شاشته.","join.fine":"لا يتصل أي شيء حتى تنقر على «انضم». تذهب كاميرتك وميكروفونك مباشرة إلى المضيف، من نظير إلى نظير عبر WebRTC ومشفّرة أثناء النقل؛ ولا يمرّ عبر خدمة إشارات عامة إلا إنشاء الاتصال. تعمل هذه الصفحة في متصفحك ولا ترفع أي شيء آخر. يستطيع المضيف سماعك وإظهارك على الهواء وكتم صوتك أو إخراجك، وتصبح جزءًا من كل ما يسجّله أو يبثّه.","join.appPrompt":"هل ثبّتَّ Freally Capture؟","join.appLink":"افتح هذه الدعوة في التطبيق بدلًا من ذلك","join.status.checking":"جارٍ التحقق من دعوتك…","join.seconds":"{{n}} ث","join.hours":"{{n}} س","join.minutes":"{{n}} د","join.status.invited":"أنت مدعو. الدعوة صالحة لنحو {{time}} أخرى — انقر على «انضم» حين تكون جاهزًا.","join.status.expired":"انتهت صلاحية هذه الدعوة — اطلب من المضيف رابطًا جديدًا.","join.status.missing":"لا توجد دعوة في هذا الرابط — افتح الرابط أو رمز QR الذي شاركه المضيف كما هو.","join.status.damaged":"تبدو هذه الدعوة تالفة — اطلب من المضيف مشاركة الرابط مرة أخرى.","join.button.mutedByHost":"كتم المضيف صوتك","join.button.unmute":"إلغاء كتم ميكروفوني","join.button.mute":"كتم ميكروفوني","join.button.stopShare":"إيقاف المشاركة","join.button.share":"مشاركة شاشتي","join.status.noReconnect":"تعذّرت إعادة الاتصال — أعد تحميل هذه الصفحة ما دامت دعوتك صالحة لتنضم من جديد.","join.status.reconnecting":"انقطع الاتصال — ستُعاد المحاولة بعد {{seconds}} ث (المحاولة {{attempt}} من {{max}})…","join.status.requesting":"جارٍ طلب الوصول إلى الكاميرا والميكروفون…","join.status.blocked":"الكاميرا أو الميكروفون محظور: {{error}} — اسمح بالوصول ثم انقر على «انضم» مرة أخرى.","join.status.reconnectedMuted":"أُعيد الاتصال — يبقى ميكروفونك مكتومًا (أنت من كتمه).","join.status.calling":"جارٍ الاتصال بالمضيف…","join.status.hostMuted":"كتم المضيف صوتك.","join.status.hostUnmuted":"ألغى المضيف كتم صوتك.","join.status.removed":"أخرجك المضيف — يبقى الرابط صالحًا إن دُعيت من جديد.","join.status.banned":"أخرجك المضيف من هذه الجلسة.","join.status.ended":"أنهى المضيف الجلسة.","join.status.callError":"خطأ في المكالمة: {{error}}","join.status.iceFailed":"فشل الاتصال المباشر — الطرفان خلف NAT صارم. يمكن للمضيف إعداد مرحّل TURN في نافذة Remote لديه.","join.status.unstable":"الاتصال غير مستقر — جارٍ محاولة استعادته…","join.status.connected":"متصل — تتم مشاركة كاميرتك وميكروفونك. أبقِ هذه الصفحة مفتوحة.","join.status.signallingLost":"انقطعت الإشارات — جارٍ إعادة الاتصال (تستمر صورتك وصوتك في التدفق)…","join.status.hostUnreachable":"تعذّر الوصول إلى المضيف — هل ما زالت جلسته قائمة؟","join.status.connectionError":"خطأ في الاتصال: {{error}}","join.status.shareBlocked":"مشاركة الشاشة محظورة: {{error}}","join.status.sharing":"تتم مشاركة شاشتك في الجلسة.","join.status.left":"غادرت الجلسة."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
